Definition rlp_decode_tx {tx_off : Z} {tx_len : Z} {public_key_off : Z}
(tx : StatelessInputSliceFields tx_off tx_len)
(pubkey : StatelessInputSliceFields public_key_off 65) (blob_limit : Z)
(*(0 <=? tx_off) && ((0 <=? tx_len) && ((tx_off + tx_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? tx_len) &&
    ((tx_len <=? (2 ^ 30)) &&
      ((0 <=? public_key_off) && ((0 <=? 65) && ((public_key_off + 65) <=? (2 ^ 32 - 1))) &&
        ((blob_limit =? 0) || ((blob_limit =? 6) || (blob_limit =? 9))))))*)
: M (Transaction) :=
   let public_key_body := stateless_input_sub_slice (pubkey) (1) (PUBLIC_KEY_BODY_LENGTH) in
   (stateless_input_keccak256 (@existT _ _ 64 (@existT _ _ (public_key_off + 1) (public_key_body)))) >>= fun public_key_hash =>
   let public_key_word := (hash_to_word (public_key_hash)).(word_value) in
   let sender := word_to_address (Build_word ((public_key_word))) in
   let tx_length := tx.(StatelessInputSliceFields_len) in
   (if Z.eqb tx_len (0) return M (mword 8) then (fatal_error (RlpDecode))  : M (mword 8)
    else (stateless_input_slice_byte (tx) (0))  : M (mword 8)) >>= fun (b0 : mword 8) =>
   let ttype : mword 8 :=
     if eq_vec ((subrange_vec_dec (b0) (7) (6))) (('b"11")) then (Ox"00")
     else b0 in
   let typed := neq_vec (ttype) ((Ox"00")) in
   (if typed return M (TransactionInputSlice) then
      (if Z.leb (1) tx_len then
         returnM ((@existT _ _ (tx_len - 1) (@existT _ _ (tx_off + 1) (stateless_input_sub_slice
                                                                         (tx) (1)
                                                                         ((Z.sub tx_len (1)))))) : {len & {off & (StatelessInputSliceFields off len)}}%type)
       else (fatal_error (RlpDecode))  : M (TransactionInputSlice))
       : M (TransactionInputSlice)
    else returnM ((@existT _ _ tx_len (@existT _ _ tx_off (tx))) : TransactionInputSlice)) >>= fun '(@existT _ _ __payload1 (@existT _ _ __payload0 payload)) =>
   let '(@existT _ _ payload_input__'len (@existT _ _ payload_input__'off payload_input)) :=
     (@existT _ _ _ (@existT _ _ _ (payload)) : StatelessInputSlice) in
   (rlp_node_cursor (payload_input)) >>= fun '(@existT _ _ __fields1 (@existT _ _ __fields0 fields)) =>
   let p0_ := ttype in
   (if eq_vec (p0_) ((Ox"00")) then returnM (LegacyTx)
    else if eq_vec (p0_) ((Ox"01")) then returnM (AccessListTx)
    else if eq_vec (p0_) ((Ox"02")) then returnM (FeeMarketTx)
    else if eq_vec (p0_) ((Ox"03")) then returnM (BlobTx)
    else if eq_vec (p0_) ((Ox"04")) then returnM (SetCodeTx)
    else (fatal_error (RlpDecode))  : M (TxType)) >>= fun (tx_type : TxType) =>
   match tx_type with
   | LegacyTx =>
      (decode_legacy_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | AccessListTx =>
      (decode_access_list_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | FeeMarketTx =>
      (decode_fee_market_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | BlobTx =>
      (decode_blob_tx (tx) (pubkey) (blob_limit) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | SetCodeTx =>
      (decode_set_code_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   end
    : M ({syn_blob_limit & (TransactionFields syn_blob_limit)}%type).

