Definition LOGS_BLOOM_BYTE_LENGTH : Z := 256.
#[export] Hint Unfold LOGS_BLOOM_BYTE_LENGTH : sail.
Definition bloom_bit_mask (bit_to_set : Z) (*(0 <=? bit_to_set) && (bit_to_set <=? 7)*) : byte :=
   shiftl ((Ox"01")) (bit_to_set).

Definition bloom_set_bit (bloom : vec (mword 8) 256) (bit_to_set : bloom_bit_index)
(*(0 <=? bit_to_set) && (bit_to_set <=? 2047)*)
: LogsBloom :=
   let bit_to_set := (bit_to_set).(bloom_bit_index_value) in
   let out := bloom in
   let quotient := e_div (bit_to_set) (8) in
   let natural_byte : Z := quotient in
   let remainder := Z.rem (bit_to_set) (8) in
   let bit_in_byte : Z := remainder in
   let mask := bloom_bit_mask (bit_in_byte) in
   vec_update_dec (out) (natural_byte) ((or_vec ((vec_access_dec (out) (natural_byte))) (mask))).

Definition bloom_add_entry_hash (bloom : vec (mword 8) 256) (h : vec (mword 8) 32) : LogsBloom :=
   let bytes := h in
   let first_bits :=
     concat_vec ((subrange_vec_dec ((vec_access_dec (bytes) (0))) (2) (0)))
       ((vec_access_dec (bytes) (1))) in
   let first_index := uint (first_bits) in
   let out := bloom_set_bit (bloom) (Build_bloom_bit_index ((first_index))) in
   let second_bits :=
     concat_vec ((subrange_vec_dec ((vec_access_dec (bytes) (2))) (2) (0)))
       ((vec_access_dec (bytes) (3))) in
   let second_index := uint (second_bits) in
   let out : vec (mword 8) 256 := bloom_set_bit (out) (Build_bloom_bit_index ((second_index))) in
   let third_bits :=
     concat_vec ((subrange_vec_dec ((vec_access_dec (bytes) (4))) (2) (0)))
       ((vec_access_dec (bytes) (5))) in
   let third_index := uint (third_bits) in
   bloom_set_bit (out) (Build_bloom_bit_index ((third_index))).

Definition bloom_add_log_at (bloom : vec (mword 8) 256) (index : log_store_index)
(*(0 <=? index) && (index <=? (2 ^ 64 - 1))*)
: M (LogsBloom) :=
   let index := (index).(log_store_index_value) in
   (log_address (Build_log_store_index ((index)))) >>= fun address =>
   (keccak256_address (address)) >>= fun address_hash =>
   let out := bloom_add_entry_hash (bloom) (address_hash) in
   let topic : Z := 0 in
   ((log_topics_count (Build_log_store_index ((index)))) >>= fun semanticResult =>
    returnM (semanticResult).(log_store_index_value)) >>= fun topic_count =>
   (whileMT
     (out, topic)
     (fun '(out, topic) => Z.sub (topic_count) (topic))
     (fun '(out, topic) => returnM ((Z.ltb (topic) (topic_count))))
     (fun '(out, topic) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        ((log_topic (Build_log_store_index ((index))) (Build_log_store_index ((topic)))) >>= fun semanticResult =>
         returnM (semanticResult).(word_value)) >>= fun topic_value =>
        (keccak256_word (Build_word ((topic_value)))) >>= fun topic_hash =>
        let out : vec (mword 8) 256 := bloom_add_entry_hash (out) (topic_hash) in
        ((log_store_index_increment (Build_log_store_index ((topic)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun (w__0 : Z) =>
        let topic := w__0  : Z in
        returnM ((out, topic)))
        : M ((vec (mword 8) 256 * Z)))) >>= fun '((out, topic)
   : (vec (mword 8) 256 * Z)) =>
   returnM (out).

Definition bloom_add_logs (bloom : vec (mword 8) 256) (logs : LogSeriesRef) : M (LogsBloom) :=
   let out := bloom in
   let offset : Z := 0 in
   (whileMT
     (offset, out)
