            (Build_log_store_index ((offset)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun index =>
        (bloom_add_log_at (out) (Build_log_store_index ((index)))) >>= fun (w__0 : vec (mword 8) 256) =>
        let out := w__0  : vec (mword 8) 256 in
        ((log_store_index_increment (Build_log_store_index ((offset)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun (w__1 : Z) =>
        let offset := w__1  : Z in
        returnM ((offset, out)))
