Definition account_info_changed (c : AccountInfo) (o : AccountInfo) : bool :=
   orb
     ((neq_int ((c.(AccountInfo_nonce)).(account_nonce_value))
         ((o.(AccountInfo_nonce)).(account_nonce_value))))
     (((orb
          ((neq_int ((c.(AccountInfo_balance)).(word_value))
              ((o.(AccountInfo_balance)).(word_value))))
          ((orb ((generic_neq (c.(AccountInfo_code_hash)) (o.(AccountInfo_code_hash))))
              ((generic_neq (c.(AccountInfo_storage_root)) (o.(AccountInfo_storage_root)))))))
      : bool)).

Definition account_info_empty (info : AccountInfo) : bool :=
   andb ((generic_eq (info.(AccountInfo_code_hash)) (KECCAK_EMPTY)))
     (((andb ((Z.eqb ((info.(AccountInfo_nonce)).(account_nonce_value)) (0)))
          ((word_is_zero ((info.(AccountInfo_balance)).(word_value)))))
      : bool)).

Definition account_changed (c : Account) (o : Account) : bool :=
   orb ((account_info_changed (c.(Account_info)) (o.(Account_info))))
     ((orb ((neq_bool (c.(Account_present)) (o.(Account_present))))
         ((neq_bool (c.(Account_storage_cleared)) (o.(Account_storage_cleared)))))).

Definition account_set_info (acc : Account) (info : AccountInfo) : Account :=
   let empty := account_info_empty (info) in
   if empty then
     {| Account_info :=
          {[ EMPTY_ACCOUNT_INFO with
            AccountInfo_storage_root := acc.(Account_info).(AccountInfo_storage_root) ]};
        Account_present := false;
        Account_storage_cleared := true;
        Account_created := acc.(Account_created);
        Account_selfdestructed := acc.(Account_selfdestructed) |}
   else
     {| Account_info := info;
        Account_present := true;
        Account_storage_cleared := acc.(Account_storage_cleared);
        Account_created := acc.(Account_created);
        Account_selfdestructed := acc.(Account_selfdestructed) |}.

Definition account_clear_storage (acc : Account) : Account :=
   {[ acc with Account_storage_cleared := true ]}.

Definition account_delete (acc : Account) : Account :=
   {| Account_info :=
        {[ EMPTY_ACCOUNT_INFO with
          AccountInfo_storage_root := acc.(Account_info).(AccountInfo_storage_root) ]};
      Account_present := false;
      Account_storage_cleared := true;
      Account_created := acc.(Account_created);
      Account_selfdestructed := acc.(Account_selfdestructed) |}.

Definition account_clear_preserving_balance (acc : Account) : Account :=
   let cleared_storage := account_clear_storage (acc) in
   account_set_info (cleared_storage)
     (let  _record := acc.(Account_info) in
     {| AccountInfo_nonce := (Build_account_nonce (0));
        AccountInfo_balance := _record.(AccountInfo_balance);
        AccountInfo_code_hash := KECCAK_EMPTY;
        AccountInfo_storage_root := _record.(AccountInfo_storage_root) |}).

Definition store_account (a : vec (mword 8) 20) (v : Account) : M (unit) :=
   (acct_tx_update (a) (v))  : M (unit).

Definition store_account_info (a : vec (mword 8) 20) (acc : Account) (info : AccountInfo) : M (unit) :=
   let empty := account_info_empty (info) in
   (if empty return M (unit) then (storage_tx_clear (a))  : M (unit)
    else returnM (tt)) >>
   let next := account_set_info (acc) (info) in
   (if orb
         ((generic_neq (next.(Account_info).(AccountInfo_storage_root))
             (acc.(Account_info).(AccountInfo_storage_root))))
         ((orb ((neq_bool (next.(Account_present)) (acc.(Account_present))))
             ((neq_bool (next.(Account_storage_cleared)) (acc.(Account_storage_cleared))))))
      return
      M (unit) then
      (store_account (a) (next))
       : M (unit)
    else
      (if neq_int ((next.(Account_info).(AccountInfo_balance)).(word_value))
            ((acc.(Account_info).(AccountInfo_balance)).(word_value))
         return
         M (unit) then
         (acct_tx_set_balance (a)
            (Build_word (((next.(Account_info).(AccountInfo_balance)).(word_value)))))
          : M (unit)
       else returnM (tt)) >>
      (if neq_int ((next.(Account_info).(AccountInfo_nonce)).(account_nonce_value))
            ((acc.(Account_info).(AccountInfo_nonce)).(account_nonce_value))
         return
         M (unit) then
         (acct_tx_set_nonce (a)
            (Build_account_nonce (((next.(Account_info).(AccountInfo_nonce)).(account_nonce_value)))))
          : M (unit)
       else returnM (tt)) >>
      (if generic_neq (next.(Account_info).(AccountInfo_code_hash))
            (acc.(Account_info).(AccountInfo_code_hash))
         return
         M (unit) then
         (acct_tx_set_code_hash (a) (next.(Account_info).(AccountInfo_code_hash)))
          : M (unit)
       else returnM (tt))
       : M (unit))
    : M (unit).

