Definition k_account_occupied (a : vec (mword 8) 20) : M (bool) :=
   (k_aload (a)) >>= fun acc =>
   let info := acc.(Account_info) in
   let anchored_storage :=
     andb ((negb (acc.(Account_storage_cleared))))
       ((generic_neq (info.(AccountInfo_storage_root)) (EMPTY_TRIE_ROOT))) in
   (if orb ((generic_neq (info.(AccountInfo_code_hash)) (KECCAK_EMPTY)))
         (((orb ((neq_int ((info.(AccountInfo_nonce)).(account_nonce_value)) (0)))
              (anchored_storage))
          : bool)) then
      returnM (true)
    else (storage_has_writes (a))  : M (bool))
    : M (bool).

Definition k_transfer (src : vec (mword 8) 20) (dst : vec (mword 8) 20) (v : word)
(*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (k_aload (src)) >>= fun src_acc =>
   (k_aload (dst)) >>= fun dst_acc =>
   let value_is_zero := word_is_zero (v) in
