   let term_index : Z := 1 in
   let output : Z := 0 in
   let numerator_accum : Z := denominator in
   (whileMT
     (numerator_accum, output, term_index)
     (fun '(numerator_accum, output, term_index) => Z.sub (scaled_limit) (output))
     (fun '(numerator_accum, output, term_index) => returnM ((Z.gtb (numerator_accum) (0))))
