Definition memory_expansion_cost {ex554890_ : Z} {ex554889_ : Z}
(mem : EvmMemorySliceFields ex554889_ ex554890_) (required_size : Z) (*0 <=? required_size*)
(*(0 <=? ex554889_) && ((0 <=? ex554890_) && ((ex554889_ + ex554890_) <=? (2 ^ 32 - 1)))*)
