   let profile := execution_profile.(ExecutionProfileFields_protocol) in
   returnM ((if Z.geb (profile.(ProtocolProfileFields_fork)) (Amsterdam) then
               if Z.leb (byte_len) (profile.(ProtocolProfileFields_deployed_code_size_limit)) then
                 let words := memory_word_count (byte_len) in
                 if Z.leb (words) ((e_div (available) (G_keccak_word))) then
