Definition bls_msm_gas
(table : vec bls_discount 128) (base : gas_constant) (maxd : bls_discount) (k : source_length)
(available : Z) (*(0 <=? base) && (base <=? 45000)*) (*(0 <=? maxd) && (maxd <=? (2 ^ 16 - 1))*)
(*(0 <=? k) && (k <=? (2 ^ 32 - 1))*) (*0 <=? available*)
: GasCharge :=
   let table := (vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (table)) in
   let base := (base).(gas_constant_value) in
   let maxd := (maxd).(bls_discount_value) in
   let k := (k).(source_length_value) in
   if Z.eqb (k) (0) then gas_charge (GAS_COST_ZERO)
   else
     let discount : Z := maxd in
     let discount : Z :=
       if Z.ltb (k) (128) then
