Definition precompile_gas (num : PrecompileId) (input : CalldataSlice) (available : Z)
(*0 <=? available*)
: M (GasCharge) :=
   let input_len := (calldata_slice_length (input)).(source_length_value) in
   let input_length := input_len in
   let words := memory_word_count (input_len) in
   match num with
   | NotPrecompile => returnM (GAS_CHARGE_UNAFFORDABLE)
   | Ecrecover => returnM ((fixed_precompile_gas (3000) (available)))
   | Sha256 =>
      returnM ((linear_gas (Build_gas_constant ((60))) (Build_gas_constant ((12)))
                  (Build_source_length ((words))) (available)))
   | Ripemd160 =>
      returnM ((linear_gas (Build_gas_constant ((600))) (Build_gas_constant ((120)))
                  (Build_source_length ((words))) (available)))
   | Identity =>
      returnM ((linear_gas (Build_gas_constant ((15))) (Build_gas_constant ((3)))
                  (Build_source_length ((words))) (available)))
   | Modexp => (modexp_gas (input) (available))  : M (GasCharge)
   | Bn254Add => returnM ((fixed_precompile_gas (150) (available)))
   | Bn254Mul => returnM ((fixed_precompile_gas (6000) (available)))
   | Bn254Pairing =>
      returnM ((linear_gas (Build_gas_constant ((45000))) (Build_gas_constant ((34000)))
                  (Build_source_length (((e_div (input_length) (192))))) (available)))
   | Blake2f =>
      ((pc_blake2_rounds (input)) >>= fun semanticResult =>
       returnM (semanticResult).(blake2_rounds_value)) >>= fun rounds =>
      returnM ((fixed_precompile_gas (rounds) (available)))
   | KzgPointEvaluation => returnM ((fixed_precompile_gas (50000) (available)))
   | BlsG1Add => returnM ((fixed_precompile_gas (375) (available)))
   | BlsG1Msm =>
      returnM ((bls_msm_gas
                  (vec_map (fun semanticValue => (Build_bls_discount (semanticValue))) (((vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (BLS_G1_DISCOUNT)))))
                  (Build_gas_constant ((12000))) (Build_bls_discount ((519)))
                  (Build_source_length (((e_div (input_length) (160))))) (available)))
   | BlsG2Add => returnM ((fixed_precompile_gas (600) (available)))
   | BlsG2Msm =>
      returnM ((bls_msm_gas
                  (vec_map (fun semanticValue => (Build_bls_discount (semanticValue))) (((vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (BLS_G2_DISCOUNT)))))
                  (Build_gas_constant ((22500))) (Build_bls_discount ((524)))
                  (Build_source_length (((e_div (input_length) (288))))) (available)))
   | BlsPairing =>
      returnM ((linear_gas (Build_gas_constant ((37700))) (Build_gas_constant ((32600)))
                  (Build_source_length (((e_div (input_length) (384))))) (available)))
   | BlsMapFpToG1 => returnM ((fixed_precompile_gas (5500) (available)))
   | BlsMapFp2ToG2 => returnM ((fixed_precompile_gas (23800) (available)))
   | P256Verify => returnM ((fixed_precompile_gas (6900) (available)))
   end
    : M (GasCharge).

