Definition legacy_sstore_costs (original : word) (current : word) (new_value : word) (cold : bool)
(*(0 <=? original) && (original <=? (2 ^ 256 - 1))*)
(*(0 <=? current) && (current <=? (2 ^ 256 - 1))*)
(*(0 <=? new_value) && (new_value <=? (2 ^ 256 - 1))*)
: M (SstoreCosts) :=
   let original := (original).(word_value) in
   let current := (current).(word_value) in
   let new_value := (new_value).(word_value) in
   let cold_cost : Z :=
     if cold then (G_cold_sload).(gas_constant_value)
     else (GAS_CONSTANT_ZERO).(gas_constant_value) in
   ((sstore_clear_refund (tt)) >>= fun semanticResult =>
    returnM (semanticResult).(gas_constant_value)) >>= fun (clear_refund : Z) =>
   let clean_change := andb ((neq_int (current) (new_value))) ((Z.eqb (original) (current))) in
   let original_is_zero := word_is_zero (original) in
   let current_is_zero := word_is_zero (current) in
   let new_value_is_zero := word_is_zero (new_value) in
   let original_is_nonzero := negb (original_is_zero) in
   let base : Z :=
     if clean_change then
       if original_is_zero then (G_sset).(gas_constant_value)
       else (G_sreset).(gas_constant_value)
     else (G_warm_access).(gas_constant_value) in
   let refund : Z :=
     if Z.eqb (current) (new_value) then 0
     else if Z.eqb (original) (current) then
       if andb (original_is_nonzero) (new_value_is_zero) then clear_refund
       else 0
     else
       let clear_delta :=
         if original_is_zero then 0
         else
           Z.add ((if current_is_zero then Z.sub (0) (clear_refund) else 0))
             ((if new_value_is_zero then clear_refund
               else 0)) in
       let reset_delta :=
         if Z.eqb (original) (new_value) then
           if original_is_zero then
             Z.sub ((G_sset).(gas_constant_value)) ((G_warm_access).(gas_constant_value))
           else Z.sub ((G_sreset).(gas_constant_value)) ((G_warm_access).(gas_constant_value))
         else 0 in
       Z.add (clear_delta) (reset_delta) in
   returnM (({| SstoreCosts_execution := Z.add (base) (cold_cost);
                SstoreCosts_refund := (Build_gas_refund (refund));
                SstoreCosts_state_charge := 0;
                SstoreCosts_state_credit := (Build_state_gas_spill (0)) |})).

Definition amsterdam_sstore_costs
(original : word) (current : word) (new_value : word) (cold : bool)
(*(0 <=? original) && (original <=? (2 ^ 256 - 1))*)
(*(0 <=? current) && (current <=? (2 ^ 256 - 1))*)
(*(0 <=? new_value) && (new_value <=? (2 ^ 256 - 1))*)
: SstoreCosts :=
   let original := (original).(word_value) in
   let current := (current).(word_value) in
   let new_value := (new_value).(word_value) in
   let changed := neq_int (current) (new_value) in
   let clean_change := andb ((Z.eqb (original) (current))) (changed) in
   let access := (amsterdam_storage_access_cost (cold)).(gas_constant_value) in
   let original_is_zero := word_is_zero (original) in
   let current_is_zero := word_is_zero (current) in
   let new_value_is_zero := word_is_zero (new_value) in
   let original_is_nonzero := negb (original_is_zero) in
   let current_is_nonzero := negb (current_is_zero) in
   let execution : Z :=
     if clean_change then Z.add (access) ((G_amsterdam_storage_write).(gas_constant_value))
     else access in
   let clear_delta :=
     if andb (changed)
          ((andb (original_is_nonzero) ((andb (current_is_nonzero) (new_value_is_zero))))) then
       (R_amsterdam_storage_clear).(gas_constant_value)
     else if andb (changed) ((andb (original_is_nonzero) (current_is_zero))) then
       Z.sub (0) ((R_amsterdam_storage_clear).(gas_constant_value))
     else 0 in
   let restore_delta :=
     if andb (changed) ((Z.eqb (original) (new_value))) then
       (G_amsterdam_storage_write).(gas_constant_value)
     else 0 in
   let refund : Z := Z.add (clear_delta) (restore_delta) in
   let state_charge : Z :=
     if andb (clean_change) (original_is_zero) then
       (G_amsterdam_state_storage_set).(state_gas_spill_value)
     else GAS_COST_ZERO in
   let state_credit : Z := 0 in
   let state_credit : Z :=
     if andb (changed) ((andb ((Z.eqb (original) (new_value))) (original_is_zero))) then
       let state_credit : Z := (G_amsterdam_state_storage_set).(state_gas_spill_value) in
       state_credit
     else state_credit in
   {| SstoreCosts_execution := execution;
      SstoreCosts_refund := (Build_gas_refund (refund));
      SstoreCosts_state_charge := state_charge;
      SstoreCosts_state_credit := (Build_state_gas_spill (state_credit)) |}.

