Definition run_modexp (input : CalldataSlice) : M (PrecompileResult) :=
   ((pc_word (input) (0) (32)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (base_len : Z) =>
   ((pc_word (input) (32) (32)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (exponent_len : Z) =>
   ((pc_word (input) (64) (32)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (modulus_len : Z) =>
   (if Z.eqb (modulus_len) (0) then returnM ((precompile_success (EMPTY_OUTPUT_SLICE)))
    else if orb ((Z.ltb (ACCELERATOR_INPUT_MAX) (base_len)))
              ((orb ((Z.ltb (ACCELERATOR_INPUT_MAX) (exponent_len)))
