      (if Z.ltb (ACCELERATOR_INPUT_MAX) (input_end) then returnM ((precompile_failure (tt)))
       else
         (accelerator_modexp (input) (Build_calldata_length ((bounded_base)))
            (Build_calldata_length ((bounded_exponent))) (Build_calldata_length ((bounded_modulus)))) >>= fun success =>
         returnM ((accelerator_result (success) (bounded_modulus))))
       : M (PrecompileResult))
    : M (PrecompileResult).

