Definition bls_g1_padding (input : CalldataSlice) (base : Z) (stride : Z) (count : Z)
(*(0 <=? base) && ((0 <=? 64) && ((base + 64) <=? (2 ^ 32 - 1))) &&
  ((0 <=? stride) && (stride <=? (2 ^ 32 - 1)) && ((0 <=? count) && (count <=? (2 ^ 32 - 1))))*)
: M (bool) :=
   (and_boolM
      ((slice_strided_zero (input) (base) (stride) (BLS_FIELD_PADDING_LENGTH) (count))
       : M (bool))
      ((slice_strided_zero (input) ((Z.add (base) (BLS_PADDED_FIELD_LENGTH))) (stride)
          (BLS_FIELD_PADDING_LENGTH) (count))
       : M (bool)))
    : M (bool).

Definition bls_g2_padding (input : CalldataSlice) (base : Z) (stride : Z) (count : Z)
