   (and_boolM
      ((slice_strided_zero (input) (base) (stride) (BLS_FIELD_PADDING_LENGTH) (count))
       : M (bool))
      ((and_boolM
          ((slice_strided_zero (input) ((Z.add (base) (BLS_PADDED_FIELD_LENGTH))) (stride)
              (BLS_FIELD_PADDING_LENGTH) (count))
           : M (bool))
          ((and_boolM
              ((slice_strided_zero (input) ((Z.add (base) (BLS_G1_POINT_LENGTH))) (stride)
                  (BLS_FIELD_PADDING_LENGTH) (count))
               : M (bool))
              ((slice_strided_zero (input) ((Z.add (base) (BLS_G2_FINAL_FIELD_OFFSET))) (stride)
                  (BLS_FIELD_PADDING_LENGTH) (count))
               : M (bool)))
           : M (bool)))
       : M (bool)))
    : M (bool).

