   | KzgPointEvaluation => (run_kzg_point_evaluation (input))  : M (PrecompileResult)
   | BlsG1Add => (run_bls_g1_add (input))  : M (PrecompileResult)
   | BlsG1Msm => (run_bls_g1_msm (input))  : M (PrecompileResult)
   | BlsG2Add => (run_bls_g2_add (input))  : M (PrecompileResult)
   | BlsG2Msm => (run_bls_g2_msm (input))  : M (PrecompileResult)
   | BlsPairing => (run_bls_pairing (input))  : M (PrecompileResult)
   | BlsMapFpToG1 => (run_bls_map_fp_to_g1 (input))  : M (PrecompileResult)
   | BlsMapFp2ToG2 => (run_bls_map_fp2_to_g2 (input))  : M (PrecompileResult)
   | P256Verify => (run_p256_verify (input))  : M (PrecompileResult)
   end
    : M (PrecompileResult).

Definition decode_single_stack_index (immediate : mword 8) : M (deep_stack_index) :=
   (let valid := deep_stack_immediate_valid (immediate) in
   assert_exp' valid "sail/evm/instructions.sail:73.16-73.17" >>= fun _ =>
   let value : Z := uint (immediate) in
   (if Z.leb (value) (90) then returnM ((Z.add (value) (145)))
    else
      assert_exp' (Z.leb (128) (value)) "sail/evm/instructions.sail:78.27-78.28" >>= fun _ =>
      returnM ((Z.sub (value) (111))))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_deep_stack_index (semanticResult)).

Definition decode_exchange_stack_indices (immediate : mword 8) : M ((stack_index * stack_index)) :=
   (let valid := exchange_immediate_valid (immediate) in
   assert_exp' valid "sail/evm/instructions.sail:87.16-87.17" >>= fun _ =>
   let shifted : mword 8 := xor_vec (immediate) ((Ox"8F")) in
   let quotient : Z := uint ((subrange_vec_dec (shifted) (7) (4))) in
   let remainder : Z := uint ((subrange_vec_dec (shifted) (3) (0))) in
   returnM ((if Z.ltb (quotient) (remainder) then (Z.add (quotient) (1), Z.add (remainder) (1))
             else (Z.add (remainder) (1), Z.sub (29) (quotient))))) >>= fun semanticResult =>
   returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((Build_stack_index (semanticValue0)), (Build_stack_index (semanticValue1)))).

