Definition do_jump (pc_in : code_pointer) (g : Z) (destination_value : word)
(*(0 <=? pc_in) && (pc_in <=? (2 ^ 32 - 1))*) (*0 <=? g*)
(*(0 <=? destination_value) && (destination_value <=? (2 ^ 256 - 1))*)
: M ((code_pointer * gas_typ)) :=
   let pc_in := (pc_in).(code_pointer_value) in
   let destination_value := (destination_value).(word_value) in
   (((frame_code_len (tt)) >>= fun semanticResult => returnM (semanticResult).(code_length_value)) >>= fun code_length =>
   (if Z.ltb (destination_value) (code_length) return M ((Z * Z)) then
      let destination : Z := destination_value in
      (frame_jumpdest_valid (destination)) >>= fun valid_destination =>
      (if valid_destination then returnM ((destination, g))
       else (exc_halt (g) (InvalidJump)) >>= fun (w__0 : Z) => returnM ((pc_in, w__0)))
       : M ((Z * Z))
    else (exc_halt (g) (InvalidJump)) >>= fun (w__2 : Z) => returnM ((pc_in, w__2)))
    : M ((Z * Z))) >>= fun semanticResult =>
   returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((Build_code_pointer (semanticValue0)), semanticValue1)).

