      returnM ((LogTopics3
                  (let '(semanticValue0, semanticValue1, semanticValue2) := ((t0, t1, t2)) in ((Build_word (semanticValue0)), (Build_word (semanticValue1)), (Build_word (semanticValue2)))), top3))
    else if Z.eqb (l__0) (4) return M ((LogTopics * mword 64)) then
