       returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((semanticValue0).(word_value), semanticValue1))) >>= fun '((t0, top1)) =>
      ((pop (top1)) >>= fun semanticResult =>
       returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((semanticValue0).(word_value), semanticValue1))) >>= fun '((t1, top2)) =>
      ((pop (top2)) >>= fun semanticResult =>
       returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((semanticValue0).(word_value), semanticValue1))) >>= fun '((t2, top3)) =>
      ((pop (top3)) >>= fun semanticResult =>
       returnM (let '(semanticValue0, semanticValue1) := semanticResult in ((semanticValue0).(word_value), semanticValue1))) >>= fun '((t3, top4)) =>
      returnM ((LogTopics4
                  (let '(semanticValue0, semanticValue1, semanticValue2, semanticValue3) := ((t0, t1, t2, t3)) in ((Build_word (semanticValue0)), (Build_word (semanticValue1)), (Build_word (semanticValue2)), (Build_word (semanticValue3)))), top4))
    else returnM ((LogTopics0 (tt), top)))
