Definition common_prefix_length (a : TriePath) (b : TriePath) : M (trie_path_len) :=
   (let alen := (path_len (a)).(trie_path_len_value) in
   let blen := (path_len (b)).(trie_path_len_value) in
   let stop := if Z.ltb (alen) (blen) then alen else blen in
   let length : Z := 0 in
   let matching : bool := true in
   (whileMT
     (length, matching)
     (fun '(length, matching) => Z.sub (stop) (length))
     (fun '(length, matching) => returnM ((andb (matching) (((Z.ltb (length) (stop))  : bool)))))
     (fun '(length, matching) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        (path_nibble (a) (Build_trie_path_cursor ((length)))) >>= fun a_nibble =>
        (path_nibble (b) (Build_trie_path_cursor ((length)))) >>= fun b_nibble =>
        (if eq_vec (a_nibble) (b_nibble) return M ((Z * bool)) then
           let current_length := length in
           (if Z.ltb (current_length) (64) then returnM ((Z.add (current_length) (1)))
            else (fatal_error (WitnessDeficient))  : M (Z)) >>= fun (w__1 : Z) =>
           let length := w__1  : Z in
           returnM ((length, matching))
         else
           let matching : bool := false in
           returnM ((length, matching)))
         : M ((Z * bool)))
        : M ((Z * bool)))) >>= fun '((length, matching)
   : (Z * bool)) =>
   returnM (length)) >>= fun semanticResult =>
   returnM (Build_trie_path_len (semanticResult)).

