      returnM ((concat_vec ((or_vec (flag) ((Ox"1")))) (first_nibble)))
    else returnM ((concat_vec (flag) ((Ox"0")))))
    : M (mword 8).

Definition scratch_hex_prefix_decode_ref {source_off : Z} {source_len : Z} {content_len : Z}
(f : ScratchRlpFieldRef source_off source_len content_len)
(*(0 <=? source_off) && ((0 <=? source_len) && ((source_off + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? content_len) && (content_len <=? source_len))*)
: M ((bool * TriePath)) :=
   (if f.(ScratchRlpFieldRef_is_list) return M (unit) then (fatal_error (RlpDecode))  : M (unit)
    else returnM (tt)) >>
   let n := f.(ScratchRlpFieldRef_content_len) in
   (if Z.eqb content_len (0) then returnM ((false, path_empty (tt)))
    else
      let maximum_length := HEX_PREFIX_MAX_LENGTH in
      (if Z.ltb (maximum_length) content_len return M ((bool * TriePath)) then
         (fatal_error (RlpDecode))
          : M ((bool * TriePath))
       else
         let content :=
           scratch_sub_slice (f.(ScratchRlpFieldRef_source)) ((Z.sub source_len content_len))
             content_len in
         (scratch_byte (content) (0)) >>= fun fb =>
         let flag : mword 4 := subrange_vec_dec (fb) (7) (4) in
         let is_leaf : bool := eq_vec ((access_vec_dec (flag) (1))) (('b"1")) in
         let odd : bool := eq_vec ((access_vec_dec (flag) (0))) (('b"1")) in
         let tail_length : Z := Z.sub content_len (1) in
         let tail := scratch_slice_suffix (content) (1) in
         ((scratch_slice_load (tail) (0)) >>= fun semanticResult =>
          returnM (semanticResult).(word_value)) >>= fun packed =>
         let paired_nibbles : Z := Z.mul (tail_length) (2) in
         (if odd return M ((bool * TriePath)) then
            (if Z.ltb (paired_nibbles) (64) then
               let shifted :=
                 (word_shift_right (Build_word ((packed))) (Build_word_bit_count ((4)))).(word_value) in
               let bytes := word_to_hash (Build_word ((shifted))) in
               let bytes : vec (mword 8) 32 :=
                 vec_update_dec (bytes) (0)
                   ((concat_vec ((subrange_vec_dec (fb) (3) (0)))
                       ((subrange_vec_dec ((vec_access_dec (bytes) (0))) (3) (0))))) in
               let path_data := B256 (bytes) in
               let path :=
                 path_new (path_data) (Build_trie_path_len (((Z.add (paired_nibbles) (1))))) in
               returnM ((is_leaf, path))
             else (fatal_error (WitnessDeficient))  : M ((bool * TriePath)))
             : M ((bool * TriePath))
          else
            let path_data := word_to_hash (Build_word ((packed))) in
            let path := path_new (path_data) (Build_trie_path_len ((paired_nibbles))) in
            returnM ((is_leaf, path)))
          : M ((bool * TriePath)))
       : M ((bool * TriePath)))
    : M ((bool * TriePath)).

