      let updated := (vec_update_dec (updated) (index) (w__0))  : vec NodeRef 16 in
      (_rec_decode_scratch_branch_node _ _ (next) ((Z.add (index) (1))) (updated)
         ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption)))
       : M (ScratchTrieNode)
    else
