   (scratch_push_b256 (root) (WORD_BYTE_LENGTH)) >>
   (scratch_push_byte ((if success then (Ox"01") else (Ox"00")))) >>
   (scratch_push_byte ((Ox"25"))) >>
   (scratch_push_byte ((Ox"00"))) >>
   (scratch_push_byte ((Ox"00"))) >> (scratch_push_byte ((Ox"00")))  : M (unit).

